INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329411, 14200, 'The Guardian', 'en', 'Oceania declares support for Infantino in boost for Fifa president but New Zealand breaks ranks', 'https://www.theguardian.com/football/2026/aug/14/oceania-football-confederation-ofc-declares-support-infantino-fifa-president', 'OFC’s 11 votes could prove crucial in Fifa election Stance shows continued backing from smaller nations The Oceania Football Confederation (OFC) has declared its support for Gianni Infantino following demands from Uefa, Concacaf and the Asian Football Confederation for the Fifa president to resign, in a development that further highlights world football’s civil war. After a meeting of its executive committee in Fiji on Wednesday, the OFC issued a statement on Friday praising “the progress achieved over the last decade” by Fifa in its first public comments since the abandoned World Cup sell-off', 'https://i.guim.co.uk/img/media/fecb596d2d0b84eec2e515b5e54f543386d643b5/0_124_4060_3249/master/4060.jpg?width=140&quality=85&auto=format&fit=max&s=168fff1e926fa74b7499b55badcdd8b7', '2026-08-14T07:13:59+00:00', '2026-08-14T14:58:21.946920'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
