INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349093, 14202, 'The Indian Express', 'en', 'NTA to reconduct UGC-NET for English, Sociology, Commerce papers as audit finds factual, translation errors', 'https://indianexpress.com/article/education/nta-re-exam-ugc-net-june-2026-for-english-sociology-commerce-papers-committee-audit-finds-factual-translation-errors-test-schedule-admit-card-10836072', '', 'https://images.indianexpress.com/2025/02/Students-and-their-parents-outside-the-examination-centre-for-JEE-main-conducted-by-National-Testing-Agency-at-an-institute-in-Mohali-on-Tuesday.-Express-Photo-1.jpg', '2026-08-16T15:11:20+00:00', '2026-08-16T21:58:37.870649'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349109, 14202, 'The Times of India', 'en', 'Exam-conducting body NTA admits errors, orders fresh NET test for 3 subjects', 'https://timesofindia.indiatimes.com/india/nta-admits-errors-orders-fresh-net-for-3-subjects/articleshow/133277880.cms', 'National Testing Agency acknowledged extensive errors in UGC-NET English, Commerce, and Sociology papers. Fresh examinations for these three subjects have been ordered by the agency. These re-tests are scheduled to take place on September 9 and 10. The decision came after multiple complaints regarding factual and typographical errors were received. Results for the other 84 subjects will be declared as scheduled.', 'https://static.toiimg.com/photo/msid-133277891,imgsize-174140.cms', '2026-08-16T15:21:14+00:00', '2026-08-16T21:58:49.844788'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
