INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349227, 14202, 'Dainik Bhaskar', 'hi', 'UGC-NET की इंग्लिश-कॉमर्स और सोशियोलॉजी की परीक्षाएं रद्द: NTA ने माना पेपर में स्पेलिंग और प्रिंटिंग की गल...', 'https://news.google.?oc=5', 'UGC-NET की इंग्लिश-कॉमर्स और सोशियोलॉजी की परीक्षाएं रद्द: NTA ने माना पेपर में स्पेलिंग और प्रिंटिंग की गल... Dainik Bhaskar', '', '2026-08-16T15:30:43+00:00', '2026-08-16T21:59:28.145435'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
