INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349316, 14202, 'Amar Ujala', 'hi', 'UGC-NET: अंग्रेजी-कॉमर्स और समाजशास्त्र की दोबारा होगी परीक्षा, प्रश्रपत्र में मिलीं कई खामियां; देखें शेड्यूल', 'https://www.amarujala.com/quotes/educational-quotes/ugc-net-2026-nta-orders-re-test-for-english-commerce-sociology-after-errors-in-question-papers-2026-08-16', 'UGC-NET2026: अंग्रेजी, कॉमर्स और समाजशास्त्र की परीक्षा दोबारा होगी, NTA ने जारी किया शेड्यूल, UGC NET 2026 NTA orders re test for English, Commerce, Sociology after errors in question papers', '', '2026-08-16T03:26:12+00:00', '2026-08-16T21:59:36.646004'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349353, 14202, 'Aaj Tak', 'hi', 'दो एग्जाम, जमकर घमासान... UGC-NET परीक्षा रद्द, बॉम्बे HC एग्जाम में गड़बड़ी, दिपके की भी एंट्री', 'https://www.aajtak.in/india/news/story/nta-ugc-net-exam-reconduct-mumbai-high-court-clerk-typing-exam-technical-issues-ntcpvp-dskc-2623504-2026-08-16', 'NTA की UGC-NET जून 2026 परीक्षा में अंग्रेजी, कॉमर्स और समाजशास्त्र विषयों के प्रश्नपत्रों में गंभीर गलतियों के कारण परीक्षा दोबारा कराने का निर्णय लिया गया है.', '', '2026-08-16T18:08:26+00:00', '2026-08-16T21:59:47.934117'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349363, 14202, 'Aaj Tak', 'hi', 'NTA की फिर किरकिरी! रद्द करनी पड़ी UGC-NET के तीन विषयों की परीक्षा', 'https://www.aajtak.in/education/story/nta-cancels-ugc-net-june-2026-english-commerce-sociology-release-new-schedule-ntc-drmt-rpti-2623449-2026-08-16', 'नेशनल टेस्टिंग एजेंसी (NTA) ने UGC-NET जून 2026 परीक्षा के तीन विषयों- अंग्रेजी, कॉमर्स और समाजशास्त्र की परीक्षा दोबारा आयोजित करने का फैसला किया है. प्रश्नपत्रों में पाई गई गलतियों के बाद ये फैसला लिया गया है. री-एग्जाम के लिए अभ्यर्थियों से कोई अतिरिक्त फीस नहीं ली जाएगी.', '', '2026-08-16T15:32:40+00:00', '2026-08-16T21:59:48.399473'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349377, 14202, 'Aaj Tak', 'hi', 'NTA कराएगा 3 विषयों का री-एग्जाम, नया शेड्यूल हुआ जारी', 'https://www.aajtak.in/short-videos/video/ugc-net-june-2026-nta-cancels-three-papers-announces-re-exam-dates-for-english-commerce-sociology-candidates-mmta-2623470-2026-08-16', 'यूजीसी नेट जून 2026 के तीन विषयों अंग्रेजी, कॉमर्स और समाजशास्त्र की परीक्षा दोबारा कराई जाएगी. एनटीए की विशेषज्ञ समिति को इन प्रश्नपत्रों में तथ्य, टाइपिंग, अनुवाद और व्याकरण से जुड़ी गंभीर गलतियां मिली थीं. री-एग्जाम के लिए अभ्यर्थियों से कोई अतिरिक्त शुल्क नहीं लिया जाएगा. अंग्रेजी और कॉमर्स की परीक्षा 9 सितंबर, जबकि समाजशास्त्र की परीक्षा 10 सितंबर को होगी. बाकी 84 विषयों के परिणाम तय कार्यक्रम के अनुसार जारी होंगे.', '', '2026-08-16T17:45:26+00:00', '2026-08-16T21:59:49.094438'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
