INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (350288, 14202, 'The Economic Times', 'en', 'UGC-NET retest for 3 papers over errors', 'https://economictimes.indiatimes.com/news/india/ugc-net-re-test-announced-for-english-commerce-sociology-papers-due-to-question-paper-errors/articleshow/133278336.cms', 'The National Testing Agency (NTA) announced on Sunday the re-test for three papers—English, Commerce and Sociology of the UGC-NET examination—after complaints were raised about errors in the question papers.The re-test for the English paper will be conducted on September 9 from 9 am to 12 noon in Shift 1, whilst the re-test for the Commerce paper is to be conducted on the same day from 3 pm to 6 pm in Shift 2.The re-test for the Sociology paper will be conducted on September 10 from 9 am to 12 noon in Shift 1.The NTA held the UGC-NET June 2026 examinations from June 22 to 30 in 87 subjects to ', '', '2026-08-16T16:03:54+00:00', '2026-08-16T22:03:12.471846'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
