INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321694, 14205, 'The Economic Times', 'en', 'Who will replace Chandra? A name does rounds', 'https://economictimes.indiatimes.com/news/company/corporate-trends/who-will-replace-chandrasekaran-at-bombay-house-a-tata-veterans-name-does-the-rounds-tata-steel-md-tv-narendran/articleshow/133205369.cms', 'The Tata group now faces the task of finding a successor to N Chandrasekaran, with Tata Steel MD TV Narendran emerging as a name in the succession discussions, after the Tata Sons chairman decided not to seek reappointment when his current term ends on February 20, 2027, as per a report by Times of India''s Reeba Zacharia.The Sir Dorabji Tata Trust has already moved to begin the succession process, but an unusual hurdle now hangs over the search for the next occupant of Bombay House.The trust said on Thursday that its nominee directors received an email from Chandrasekaran on August 12 informin', '', '2026-08-13T09:20:34+00:00', '2026-08-13T22:51:35.965076'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
